import{_ as e,o as a,c as s,ao as n}from"./chunks/framework.VbdOMgFa.js";const m=JSON.parse('{"title":"GPU streams and synchronization","description":"","frontmatter":{},"headers":[],"relativePath":"stream_semantics.md","filePath":"stream_semantics.md","lastUpdated":null}'),i={name:"stream_semantics.md"};function l(o,t,r,d,c,h){return a(),s("div",null,[...t[0]||(t[0]=[n(`<h1 id="stream-semantics" tabindex="-1">GPU streams and synchronization <a class="header-anchor" href="#stream-semantics" aria-label="Permalink to &quot;GPU streams and synchronization {#stream-semantics}&quot;">​</a></h1><p><a href="/ImplicitGlobalGrid.jl/previews/PR148/api#ImplicitGlobalGrid.update_halo!"><code>update_halo!</code></a> runs on streams of its own: it does not wait for work enqueued before the call, which must therefore be synchronized before, and it returns once the halo update is complete (see <a href="/ImplicitGlobalGrid.jl/previews/PR148/usage#usage-stream-ordering">Asynchronous halo updates and overlap with computation</a>).</p><p>CUDA.jl (from v6.3) and AMDGPU.jl moreover record the stream that last used an array and make a use on another stream wait for it (<em>implicit synchronization</em>). For <code>update_halo!</code>, this means:</p><ul><li><p>It does not replace the synchronization before the call: it orders the kernels that <code>update_halo!</code> uses for dimension 1 after preceding work on the array, but not the memory copies it uses for dimensions 2 and 3.</p></li><li><p>It prevents overlapping the computation of an array with the update of its halo. To overlap them, disable it for the arrays concerned and order the work explicitly:</p></li></ul><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CUDA</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">enable_synchronization!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(A, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># AMDGPU.enable_synchronization!(A, false) with AMDGPU.jl ≥ FILL</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ... computation of A on another stream, update_halo!(A), synchronization of that stream ...</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CUDA</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">enable_synchronization!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(A, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p><code>@hide_communication</code> and <code>@overlap</code> of <a href="https://github.com/omlins/ParallelStencil.jl" target="_blank" rel="noreferrer">ParallelStencil.jl</a> do this automatically (from ParallelStencil FILL on).</p><h2 id="stream-semantics-versions" tabindex="-1">Behaviour per version <a class="header-anchor" href="#stream-semantics-versions" aria-label="Permalink to &quot;Behaviour per version {#stream-semantics-versions}&quot;">​</a></h2><p>A kernel uses the array <code>A</code> on stream <code>s1</code>; while it runs, <code>A</code> or another array is used on stream <code>s2</code>. <em>Host waits</em>: the call returns only once <code>s1</code> is done. <em>GPU waits</em>: the call returns, but the work on <code>s2</code> starts only once <code>s1</code> is done. <em>Concurrent</em>: no wait.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Use on <code>s2</code></th><th style="text-align:left;">CUDA.jl 5.4–6.2</th><th style="text-align:left;">CUDA.jl 6.3–6.4</th><th style="text-align:left;">CUDA.jl ≥ 6.5</th><th style="text-align:left;">AMDGPU.jl ≥ 2.8</th></tr></thead><tbody><tr><td style="text-align:left;">Kernel launch using <code>A</code></td><td style="text-align:left;">concurrent</td><td style="text-align:left;">host waits</td><td style="text-align:left;">GPU waits</td><td style="text-align:left;">host waits</td></tr><tr><td style="text-align:left;"><code>pointer(A)</code> (e.g. for a memory copy)</td><td style="text-align:left;">concurrent</td><td style="text-align:left;">host waits</td><td style="text-align:left;">host waits</td><td style="text-align:left;">host waits</td></tr><tr><td style="text-align:left;"><code>pointer(A)</code>, if <code>s1</code> is the task-local stream</td><td style="text-align:left;">concurrent</td><td style="text-align:left;">concurrent</td><td style="text-align:left;">concurrent</td><td style="text-align:left;">concurrent</td></tr><tr><td style="text-align:left;">Kernel launch using another array</td><td style="text-align:left;">concurrent</td><td style="text-align:left;">concurrent</td><td style="text-align:left;">concurrent</td><td style="text-align:left;">concurrent</td></tr><tr><td style="text-align:left;">Any of the above after <code>enable_synchronization!(A, false)</code></td><td style="text-align:left;">concurrent</td><td style="text-align:left;">concurrent</td><td style="text-align:left;">concurrent</td><td style="text-align:left;">concurrent</td></tr></tbody></table><p>This table is checked weekly on Nvidia GH200 and AMD MI250X GPUs with an old and the latest version of each package (see <a href="/ImplicitGlobalGrid.jl/previews/PR148/testing#Continuous-integration">Continuous integration</a>).</p>`,10)])])}const u=e(i,[["render",l]]);export{m as __pageData,u as default};
